package io.github.antctrlwin.anomalib4j.evaluation;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Validates the frozen lossless map format {@code npy+json/v1} end to end against
 * fixtures generated by {@code tools/prerun/map_io.py}: the Java reader must
 * recover the exact float values, shape, dtype and metadata.
 */
class NpyMapTest {
    private static final Path DIRECTORY = Path.of("docs", "benchmark", "benchmark-prerun", "map-format");
    private static final Map<String, String> DESCRIPTORS = Map.of("float32", "<f4", "float64", "<f8");

    @Test void readsCommittedFixturesLosslessly() throws Exception {
        Path manifest = DIRECTORY.resolve("fixtures.json");
        assertTrue(Files.exists(manifest), "Missing map fixtures: " + manifest.toAbsolutePath());
        JsonNode root = new ObjectMapper().readTree(Files.readString(manifest));
        assertEquals("npy+json/v1", root.path("format").asText());

        int fixtures = 0;
        for (JsonNode node : root.withArray("fixtures")) {
            Path arrayPath = DIRECTORY.resolve(node.path("array").asText());
            NpyMap.Map map = NpyMap.read(arrayPath);

            int rows = node.path("shape").get(0).asInt();
            int columns = node.path("shape").get(1).asInt();
            assertEquals(rows, map.rows(), node.path("id").asText() + " rows");
            assertEquals(columns, map.columns(), node.path("id").asText() + " columns");
            assertEquals(DESCRIPTORS.get(node.path("dtype").asText()), map.descr(), node.path("id").asText() + " dtype");

            JsonNode expected = node.withArray("values");
            assertEquals(rows * columns, expected.size());
            assertEquals(map.values().length, expected.size());
            for (int i = 0; i < map.values().length; i++) {
                assertEquals(expected.get(i).doubleValue(), map.values()[i], 0.0,
                        node.path("id").asText() + " value[" + i + "]");
            }

            NpyMap.Sidecar sidecar = NpyMap.readSidecar(arrayPath);
            assertEquals("npy+json/v1", sidecar.format());
            assertEquals(node.path("filename").asText(), sidecar.filename());
            assertEquals(node.path("geometry_id").asText(), sidecar.geometryId());
            assertEquals(node.path("score_kind").asText(), sidecar.scoreKind());
            assertEquals(node.path("dtype").asText(), sidecar.dtype());
            assertArrayEquals(new int[]{rows, columns}, sidecar.shape());
            assertEquals(node.path("array").asText(), sidecar.array());
            assertEquals(node.path("sha256").asText(), sidecar.sha256());
            assertEquals(sidecar.sha256(), NpyMap.sha256(arrayPath), "payload hash");
            fixtures++;
        }
        assertTrue(fixtures >= 2, "Expected at least two fixtures (native + evaluated)");
    }

    @Test void rejectsForeignPayload() throws Exception {
        Path temporary = Files.createTempFile("npy", ".npy");
        try {
            Files.writeString(temporary, "not a numpy array");
            assertThrows(Exception.class, () -> NpyMap.read(temporary));
        } finally {
            Files.deleteIfExists(temporary);
        }
    }
}
